<?php require 'config.php'; $orders=[]; if(current_user()){$q=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$q->execute([current_user()['id']]);$orders=$q->fetchAll();} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My orders</title><link rel="stylesheet" href="assets/css/store-theme.css"></head><body><header class="store-header"><a class="store-logo" href="index.php">🛒 Mahavir Provision Store</a><a href="index.php">Shop</a></header><main class="store-container"><h1>My orders</h1><?php if(!current_user()):?><p>Please <a href="login.php">login</a> to see your orders.</p><?php else:?><section class="panel"><div class="table-wrap"><table><thead><tr><th>ORDER</th><th>TOTAL</th><th>STATUS</th><th>DATE</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td>₹<?=number_format((float)$o['total'],2)?></td><td><?=e($o['status'])?></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></main></body></html>